/**
 * summary promptfoo output vs committed snapshot parity test.
 *
 * The committed snapshot (`evals/promptfoo/snapshots/summary-smoke.json`) was
 * generated by running the summary bridge through the promptfoo engine with the
 * fallback judge. Following the existing summary test pattern, this test mocks
 * the retrieval adapters so the bridge plumbing is verified deterministically
 * and DB-free; the deterministic fallback judge on the mocked execution must
 * reproduce the committed per-case snapshot (caseId + passed + groundedness /
 * coverage).
 */

import { readFileSync } from 'node:fs';

import { describe, expect, it, vi } from 'vitest';

// Mock the retrieval adapters before importing the modules that use them.
vi.mock('../retrieval/lib/adapters.js', () => ({
  closeExecutionContext: vi.fn().mockResolvedValue(undefined),
  createActorSession: vi.fn().mockResolvedValue(undefined),
  createExecutionContext: vi.fn().mockResolvedValue({}),
  executeThroughRoute: vi.fn().mockResolvedValue({
    result: {
      rawResponse: {
        summary: {
          text: 'Docker container startup healthcheck timeout is fixed by increasing the healthcheck interval.',
        },
        capsules: [
          { content: 'Docker healthcheck', problem: 'startup timeout', goal: 'detect timeout' },
        ],
      },
    },
  }),
  seedScenarioFixtures: vi.fn().mockResolvedValue(undefined),
}));

import { summaryBridge } from '../summary/bridge.js';
import { getSnapshotSuiteConfigs, snapshotFilePath } from './scripts/generate-snapshots.js';
import { runSuiteWithPromptfoo } from './runner.js';
import { suiteSnapshotSchema } from './snapshots/snapshot-schema.js';

describe('summary promptfoo output matches committed snapshot', () => {
  it('reproduces the smoke snapshot per-case', async () => {
    const config = getSnapshotSuiteConfigs().find((c) => c.suiteId === 'summary');
    expect(config).toBeDefined();
    expect(config!.opts.tier).toBe('smoke');

    const { report, caseCount } = await runSuiteWithPromptfoo(summaryBridge, config!.opts);
    const entries = config!.extract(report).sort((a, b) => a.caseId.localeCompare(b.caseId));

    const snapshot = suiteSnapshotSchema.parse(
      JSON.parse(readFileSync(snapshotFilePath('summary'), 'utf8')),
    );

    expect(snapshot.cases.length).toBeGreaterThan(0);
    expect(caseCount).toBe(snapshot.cases.length);
    expect(entries).toEqual(snapshot.cases);
  });
});
